import { ACTIVITY_TYPES, type ActivityType } from '../types/health.js';

/**
 * Story 402. Which Google Calendar events are workouts, and of what type — a synced `settings` row
 * the owner edits from the app, so a new gym's wording needs no code or env change. It replaced
 * `HEALTH_CALENDAR_KEYWORDS` and the hard-coded type chain in the server's calendar service;
 * migration 041 seeded it with what those said.
 *
 * Matching is a case-insensitive substring of the event title, and the first rule that matches
 * sets the type. No regex: the wording is typed on a phone.
 */
export const CALENDAR_WORKOUT_RULES_KEY = 'health.calendar_workout_rules';

export interface CalendarWorkoutRule {
    /** Wording the event title must contain, any case. */
    match: string;
    type: ActivityType;
}

function isActivityType(value: unknown): value is ActivityType {
    return typeof value === 'string' && (ACTIVITY_TYPES as readonly string[]).includes(value);
}

/** Throws on the first rule that is not a usable `{ match, type }`, or a repeated wording. */
function assertRules(value: unknown): asserts value is CalendarWorkoutRule[] {
    if (!Array.isArray(value)) {
        throw new Error(`${CALENDAR_WORKOUT_RULES_KEY} must be a JSON array, got ${JSON.stringify(value)}`);
    }
    const seen = new Set<string>();
    value.forEach((rule: unknown, index) => {
        const { match, type } = (rule ?? {}) as Record<string, unknown>;
        if (typeof match !== 'string' || match.trim() === '') {
            throw new Error(`${CALENDAR_WORKOUT_RULES_KEY}[${index}]: match must be non-empty text, got ${JSON.stringify(rule)}`);
        }
        if (match !== match.trim()) {
            throw new Error(`${CALENDAR_WORKOUT_RULES_KEY}[${index}]: match ${JSON.stringify(match)} has surrounding spaces`);
        }
        if (!isActivityType(type)) {
            throw new Error(`${CALENDAR_WORKOUT_RULES_KEY}[${index}]: unknown type ${JSON.stringify(type)}`);
        }
        const key = match.toLowerCase();
        if (seen.has(key)) {
            throw new Error(`${CALENDAR_WORKOUT_RULES_KEY}[${index}]: ${JSON.stringify(match)} is already a rule`);
        }
        seen.add(key);
    });
}

/**
 * The rules from the stored setting value. Fails loudly: a missing row, broken JSON or a bad rule
 * throws rather than falling back to defaults, which would hide that the calendar stopped matching.
 */
export function parseCalendarWorkoutRules(value: string | null): CalendarWorkoutRule[] {
    if (value === null) throw new Error(`settings row ${CALENDAR_WORKOUT_RULES_KEY} is missing`);
    let parsed: unknown;
    try {
        parsed = JSON.parse(value);
    } catch (err) {
        throw new Error(`${CALENDAR_WORKOUT_RULES_KEY} is not JSON: ${(err as Error).message}`, { cause: err });
    }
    assertRules(parsed);
    return parsed.map(({ match, type }) => ({ match, type }));
}

/** The setting value for these rules; throws on the same problems {@link parseCalendarWorkoutRules} does. */
export function serializeCalendarWorkoutRules(rules: readonly CalendarWorkoutRule[]): string {
    assertRules(rules);
    return JSON.stringify(rules.map(({ match, type }) => ({ match, type })));
}

/** The first rule whose wording the title contains, any case; null when none does. */
export function matchCalendarWorkoutRule(summary: string, rules: readonly CalendarWorkoutRule[]): CalendarWorkoutRule | null {
    const lower = summary.toLowerCase();
    return rules.find((rule) => lower.includes(rule.match.toLowerCase())) ?? null;
}
