import {
    CALENDAR_WORKOUT_RULES_KEY,
    createSettingsRepository,
    parseCalendarWorkoutRules,
    serializeCalendarWorkoutRules,
    type CalendarWorkoutRule,
    type DbDriver,
} from '@motivation/shared';
import { DbService, LocalDbUnavailableError } from '../db/db.service.js';
import { requestSync } from './sync/auto-sync.js';

/**
 * Story 402 — the calendar workout rules, a synced `settings` row the server's calendar service
 * reads to decide which events are workouts. Written to the local DB and synced like the health
 * targets (story 258), so an edit made offline reaches the server on the next sync.
 */

export interface CalendarWorkoutRulesServiceDeps {
    driver?: () => Promise<DbDriver>;
    sync?: () => void;
}

/**
 * Waits out the bootstrap first: on a fresh phone the `settings` table only exists once the first
 * snapshot is imported, and the agenda or settings screen can be the first screen opened (the
 * story-198 transient). A bootstrap that failed has no replica to read, so it says that instead.
 */
async function defaultDriver(): Promise<DbDriver> {
    const service = DbService.getInstance();
    if (await service.whenBootstrapComplete() === 'failed') {
        throw new LocalDbUnavailableError(new Error('calendar workout rules need the local database'));
    }
    await service.init();
    return service.driver;
}

export class CalendarWorkoutRulesService {
    private readonly driverFn: () => Promise<DbDriver>;
    private readonly sync: () => void;

    constructor(deps: CalendarWorkoutRulesServiceDeps = {}) {
        this.driverFn = deps.driver ?? defaultDriver;
        this.sync = deps.sync ?? (() => requestSync('settings'));
    }

    /** Throws on a missing or broken row, like the server does. */
    async getRules(): Promise<CalendarWorkoutRule[]> {
        const settings = createSettingsRepository(await this.driverFn());
        return parseCalendarWorkoutRules(await settings.get(CALENDAR_WORKOUT_RULES_KEY));
    }

    /** Replaces the whole list; throws before writing anything when a rule is invalid. */
    async saveRules(rules: readonly CalendarWorkoutRule[]): Promise<void> {
        const value = serializeCalendarWorkoutRules(rules);
        await createSettingsRepository(await this.driverFn()).set(CALENDAR_WORKOUT_RULES_KEY, value);
        this.sync();
    }

    async addRule(rule: CalendarWorkoutRule): Promise<void> {
        await this.saveRules([...(await this.getRules()), rule]);
    }
}

export const calendarWorkoutRulesService = new CalendarWorkoutRulesService();
